css:
table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
}
th, td {
    border: 1px solid #000;
    padding: 4px;
    text-align: right;
}
th {
    text-align: center;
    font-weight: bold;
}
.left {
    text-align: left;
}
.bold {
    font-weight: bold;
}
.no-border td {
    border: none;
}
